(()=>{const q=s=>[...document.querySelectorAll(s)];
 const cards=q(".mm-card").filter(c=>c.dataset.uid).map(c=>{const r=c.getBoundingClientRect();
   return {uid:c.dataset.uid,label:c.getAttribute("aria-label"),dis:c.getAttribute("aria-disabled"),
           x:Math.round(r.x+r.width/2),y:Math.round(r.y+r.height*0.75)}});
 const es=q(".cb-enemy").map(e=>{const r=e.getBoundingClientRect();const t=e.innerText.replace(/\n/g,"|");
   return {t,x:Math.round(r.x+r.width/2),y:Math.round(r.y+r.height*0.45),dead:e.className.includes("is-dead")}});
 const nerve=(document.querySelector(".cb-nerve,[class*=nerve]")||{}).innerText||"";
 const hud=(document.querySelector(".mm-hud__courage")||{}).getAttribute?
   document.querySelector(".mm-hud__courage").getAttribute("aria-label"):"";
 return JSON.stringify({scene:window.MM.state().scene,cards,es,nerve,hud,
   end:!!document.querySelector("#end-turn,.cb-endturn,[class*=endturn]")})})()

